// JAH demo program — Live probability update demo
"use strict";
var __checks=[];
function check(l,g,w){__checks.push([l,g,w]);}
function probsAfter(gates){ var s=[1,0]; gates.forEach(function(g){
  var h=1/Math.sqrt(2); var n0=g==='H'?(s[0]+s[1])*h:s[0], n1=g==='H'?(s[0]-s[1])*h:(g==='X'?s[0]:s[1]);
  s=g==='X'?[s[1],s[0]]:[n0,n1]; }); return s.map(function(a){return Math.round(a*a*100)/100;}); }
check("H \u2192 50/50", probsAfter(['H']).join('/'), "0.5/0.5");
check("H then X \u2192 50/50", probsAfter(['H','X']).join('/'), "0.5/0.5");
check("X \u2192 |1>", probsAfter(['X']).join('/'), "0/1");
var __ok=true;
__checks.forEach(function(c){var ok=String(c[1])===String(c[2]);__ok=ok&&__ok;console.log((ok?"PASS":"FAIL")+" | "+c[0]+" => "+c[1]);});
console.log(__ok?"ALL CHECKS PASSED":"SOME CHECKS FAILED");
if(!__ok){throw new Error("demo self-check failed");}

