// JAH demo program — Confusion-matrix inversion (2 outcomes)
"use strict";
var __checks=[];
function check(l,g,w){__checks.push([l,g,w]);}
function correct(counts, p01, p10){ var n0=counts[0], n1=counts[1];
  var t0=(n0*(1-p10)-n1*p01)/((1-p01)*(1-p10)-p01*p10);
  var t1=(n1*(1-p01)-n0*p10)/((1-p01)*(1-p10)-p01*p10); return [t0,t1]; }
var c=correct([900,100],0.05,0.05);
check("corrected |0> \u2248 944", Math.round(c[0]), 944);
check("correction shifts counts up", c[0]>900, true);
var __ok=true;
__checks.forEach(function(c){var ok=String(c[1])===String(c[2]);__ok=ok&&__ok;console.log((ok?"PASS":"FAIL")+" | "+c[0]+" => "+c[1]);});
