// JAH demo program — Lint rule demo
"use strict";
var __checks=[];
function check(l,g,w){__checks.push([l,g,w]);}
function lint(ops){ var warns=[]; var measured={};
  ops.forEach(function(op){ if(op[0]==='measure')measured[op[1]]=1;
    if(op[0]==='H'&&measured[op[1]])warns.push('use after measure on q'+op[1]); });
  return warns; }
check("flags use-after-measure", lint([['measure',0],['H',0]]).length, 1);
